{"content": "from typing import Annotated, Any, List

from pydantic import AfterValidator, BaseModel, field_validator


def _lower(v: str) -> str:
    return v.lower()


# Pydantic v2 has no `each_item=True`; apply per-item logic via Annotated.
Tag = Annotated[str, AfterValidator(_lower)]


class Article(BaseModel):
    title: str
    tags: List[Tag]

    @field_validator("tags", mode="before")
    @classmethod
    def split_tags(cls, v: Any) -> Any:
        if isinstance(v, str):
            return [t for t in (p.strip() for p in v.split(",")) if t]
        return v
"}
